SELECT e.FirstName, e.LastName, m.FirstName AS manager_first, m.LastName AS manager_last
FROM Employee e
JOIN Employee m ON m.EmployeeId = e.ReportsTo;

SELECT LastName, FirstName, BirthDate
FROM Employee
WHERE Title = 'Sales Support Agent';

SELECT COUNT(*) AS n_customers
FROM Customer
WHERE Country = 'Brasil';

SELECT ROUND(SUM(Total), 2) AS revenue
FROM Invoice
WHERE InvoiceDate >= '2025-01-01' AND InvoiceDate <= '2025-03-31';

SELECT COUNT(*) AS n_invoices
FROM Invoice
WHERE Total > 13.86;

SELECT e.FirstName, e.LastName, m.FirstName AS manager_first, m.LastName AS manager_last
FROM Employee e
LEFT JOIN Employee m ON m.ReportsTo = e.EmployeeId;
